    <script>
      const form = document.getElementById("quiz-form");
      const result = document.getElementById("result");

      const answerKey = {
        q1: ["CSS", "Sass"],
        q2: ["Go", "Rust", "Python"],
        q3: ["HTML", "SQL"],
      };

      const getCheckedValues = (name) =>
        Array.from(form.querySelectorAll(`input[name="${name}"]:checked`)).map(
          (input) => input.value
        );

      const arraysMatch = (selected, correct) => {
        const normalizedSelected = [...selected].sort();
        const normalizedCorrect = [...correct].sort();

        return (
          normalizedSelected.length === normalizedCorrect.length &&
          normalizedSelected.every((value, index) => value === normalizedCorrect[index])
        );
      };

      const setQuestionValidity = (questionName, hasError) => {
        const field = form.querySelector(`[data-question="${questionName}"]`);
        const error = document.getElementById(`${questionName}-error`);
        const firstInput = field.querySelector(`input[name="${questionName}"]`);

        field.dataset.invalid = hasError ? "true" : "false";
        error.hidden = !hasError;
        firstInput.setAttribute("aria-invalid", hasError ? "true" : "false");
      };

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        let score = 0;
        let firstInvalidInput = null;

        Object.entries(answerKey).forEach(([questionName, correctAnswers]) => {
          const selectedAnswers = getCheckedValues(questionName);
          const hasError = selectedAnswers.length === 0;

          setQuestionValidity(questionName, hasError);

          if (hasError && !firstInvalidInput) {
            firstInvalidInput = form.querySelector(`input[name="${questionName}"]`);
          }

          if (!hasError && arraysMatch(selectedAnswers, correctAnswers)) {
            score += 1;
          }
        });

        if (firstInvalidInput) {
          result.dataset.state = "";
          result.textContent = "Please answer every question before submitting.";
          firstInvalidInput.focus();
          return;
        }

        result.dataset.state = "success";
        result.textContent = `You got ${score} out of ${Object.keys(answerKey).length} questions exactly right.`;
      });
